1	import fs from 'fs';
2	import path from 'path';
3	import { JSDOM } from 'jsdom';
4	import { Readability } from '@mozilla/readability';
5	import { neuralForge } from './neuralForgeService';
6	import { notebookTranscribe } from './notebookTranscribeService';
7	import { NotebookService } from './notebookService';
8	import { SystemConfig } from '../config/SystemConfig';
9	
10	const AUDIO_EXTS = new Set(['.mp3', '.mp4', '.m4a', '.wav', '.ogg', '.flac', '.webm']);
11	
12	export interface IngestResult {
13	    sourceId: number;
14	    chunkCount: number;
15	    wordCount: number;
16	}
17	
18	export class NotebookIngestService {
19	    private notebookService: NotebookService;
20	
21	    constructor(notebookService: NotebookService) {
22	        this.notebookService = notebookService;
23	    }
24	
25	    async ingestFile(notebookId: number, filePath: string, mimeType: string, originalName: string): Promise<IngestResult> {
26	        const ext = path.extname(originalName).toLowerCase();
27	        const stats = fs.statSync(filePath);
28	
29	        let text = '';
30	        let sourceType: 'pdf' | 'docx' | 'audio' | 'video' | 'url' | 'obsidian' = 'pdf';
31	        let metadata: Record<string, unknown> = {};
32	
33	        if (ext === '.pdf' || mimeType === 'application/pdf') {
34	            sourceType = 'pdf';
35	            text = await this.extractPdf(filePath);
36	        } else if (ext === '.docx' || mimeType.includes('wordprocessingml')) {
37	            sourceType = 'docx';
38	            text = await this.extractDocx(filePath);
39	        } else if (AUDIO_EXTS.has(ext) || mimeType.startsWith('audio/') || mimeType.startsWith('video/')) {
40	            sourceType = ext === '.mp4' || mimeType.startsWith('video/') ? 'video' : 'audio';
41	            const transcript = await notebookTranscribe.transcribe(filePath);
42	            text = transcript.text;
43	            metadata = { provider: transcript.provider, durationSeconds: transcript.durationSeconds };
44	        } else {
45	            throw new Error(`Unsupported file type: ${ext}`);
46	        }
47	
48	        const source = this.notebookService.createSource(notebookId, sourceType, originalName, {
49	            originPath: filePath,
50	            fileSizeBytes: stats.size,
51	            mimeType,
52	            metadata
53	        });
54	
55	        return this.processTextIntoChunks(source.id, text);
56	    }
57	
58	    async ingestUrl(notebookId: number, url: string): Promise<IngestResult> {
59	        const source = this.notebookService.createSource(notebookId, 'url', url, {
60	            originPath: url
61	        });
62	
63	        try {
64	            this.notebookService.updateSourceStatus(source.id, 'processing');
65	            const text = await this.fetchAndExtractUrl(url);
66	            return await this.processTextIntoChunks(source.id, text);
67	        } catch (e: any) {
68	            this.notebookService.updateSourceStatus(source.id, 'error', e.message);
69	            throw e;
70	        }
71	    }
72	
73	    async ingestObsidianNote(notebookId: number, vaultRelativePath: string): Promise<IngestResult> {
74	        const fullPath = SystemConfig.resolve(vaultRelativePath);
75	        if (!fs.existsSync(fullPath)) throw new Error(`Vault note not found: ${vaultRelativePath}`);
76	
77	        const raw = fs.readFileSync(fullPath, 'utf-8');
78	        // Strip YAML frontmatter
79	        const text = raw.replace(/^---[\s\S]*?---\n?/, '').trim();
80	        const title = path.basename(vaultRelativePath, '.md');
81	
82	        const source = this.notebookService.createSource(notebookId, 'obsidian', title, {
83	            obsidianPath: vaultRelativePath,
84	            fileSizeBytes: Buffer.byteLength(raw, 'utf-8')
85	        });
86	
87	        return this.processTextIntoChunks(source.id, text);
88	    }
89	
90	    private async extractPdf(filePath: string): Promise<string> {
91	        const pdfParse: (buf: Buffer) => Promise<{ text: string }> = require('pdf-parse');
92	        const buffer = fs.readFileSync(filePath);
93	        const result = await pdfParse(buffer);
94	        return result.text;
95	    }
96	
97	    private async extractDocx(filePath: string): Promise<string> {
98	        const mammoth = await import('mammoth');
99	        const result = await mammoth.extractRawText({ path: filePath });
100	        return result.value;
101	    }
102	
103	    private async fetchAndExtractUrl(url: string): Promise<string> {
104	        const resp = await fetch(url, {
105	            headers: { 'User-Agent': 'Mozilla/5.0 (compatible; NUDIMMUD/1.0)' },
106	            signal: AbortSignal.timeout(15000)
107	        });
108	        if (!resp.ok) throw new Error(`HTTP ${resp.status} fetching ${url}`);
109	        const html = await resp.text();
110	
111	        const dom = new JSDOM(html, { url });
112	        const reader = new Readability(dom.window.document);
113	        const article = reader.parse();
114	        return article?.textContent?.trim() || dom.window.document.body?.textContent?.trim() || '';
115	    }
116	
117	    private async processTextIntoChunks(sourceId: number, text: string): Promise<IngestResult> {
118	        try {
119	            this.notebookService.updateSourceStatus(sourceId, 'processing');
120	
121	            const words = text.split(/\s+/).filter(Boolean);
122	            const wordCount = words.length;
123	            const rawChunks = this.chunkText(words);
124	
125	            this.notebookService.saveChunks(sourceId, rawChunks);
126	            this.notebookService.updateSourceStatus(sourceId, 'processing', undefined, wordCount);
127	
128	            // Embed asynchronously (don't block the response)
129	            this.embedAllChunks(sourceId, rawChunks.length).catch(e =>
130	                console.error(`⬡ NOTEBOOK_EMBED_ERROR :: source=${sourceId} :: ${e.message}`)
131	            );
132	
133	            // Set status to ready immediately — embeddings fill in async
134	            this.notebookService.updateSourceStatus(sourceId, 'ready', undefined, wordCount);
135	
136	            return { sourceId, chunkCount: rawChunks.length, wordCount };
137	        } catch (e: any) {
138	            this.notebookService.updateSourceStatus(sourceId, 'error', e.message);
139	            throw e;
140	        }
141	    }
142	
143	    private chunkText(words: string[], windowTokens = 512, overlapTokens = 64): Array<{ content: string; tokenCount: number }> {
144	        const wordsPerWindow = Math.floor(windowTokens / 1.35);
145	        const wordsPerOverlap = Math.floor(overlapTokens / 1.35);
146	        const minWords = Math.floor(50 / 1.35);
147	        const chunks: Array<{ content: string; tokenCount: number }> = [];
148	
149	        let start = 0;
150	        while (start < words.length) {
151	            const end = Math.min(start + wordsPerWindow, words.length);
152	            const slice = words.slice(start, end);
153	            if (slice.length >= minWords) {
154	                const content = slice.join(' ');
155	                chunks.push({ content, tokenCount: Math.ceil(slice.length * 1.35) });
156	            }
157	            if (end >= words.length) break;
158	            start += (wordsPerWindow - wordsPerOverlap);
159	        }
160	        return chunks;
161	    }
162	
163	    private async embedAllChunks(sourceId: number, expectedCount: number): Promise<void> {
164	        const chunks = this.notebookService.getChunksForSource(sourceId);
165	        for (const chunk of chunks) {
166	            const embedding = await neuralForge.getEmbedding(chunk.content);
167	            if (embedding) {
168	                this.notebookService.updateChunkEmbedding(chunk.id, embedding);
169	            }
170	        }
171	        console.log(`⬡ NOTEBOOK_EMBED_DONE :: source=${sourceId} :: ${chunks.length}/${expectedCount} chunks embedded`);
172	    }
173	}
