1	import { NotebookService, NotebookChunk } from './notebookService';
2	import { neuralForge } from './neuralForgeService';
3	
4	const OLLAMA_BASE = process.env.OLLAMA_BASE_URL || 'http://localhost:11434';
5	const TOP_K = 5;
6	
7	export interface RagCitation {
8	    chunk_id: number;
9	    source_title: string;
10	    excerpt: string;
11	}
12	
13	export interface StreamRagOptions {
14	    notebookId: number;
15	    query: string;
16	    modelId: string;
17	    onToken: (token: string) => void;
18	    onCitation: (citation: RagCitation) => void;
19	    onDone: (fullContent: string) => void;
20	    onError: (msg: string) => void;
21	    signal?: AbortSignal;
22	}
23	
24	type EmbeddedChunk = NotebookChunk & { source_title: string };
25	
26	export class NotebookRagService {
27	    private notebookService: NotebookService;
28	
29	    constructor(notebookService: NotebookService) {
30	        this.notebookService = notebookService;
31	    }
32	
33	    async streamAnswer(opts: StreamRagOptions): Promise<void> {
34	        const { notebookId, query, modelId, onToken, onCitation, onDone, onError, signal } = opts;
35	
36	        const embeddedChunks = this.notebookService.getEmbeddedChunks(notebookId);
37	        if (embeddedChunks.length === 0) {
38	            onError('No embedded sources in this notebook yet. Please wait for ingestion to complete.');
39	            return;
40	        }
41	
42	        const queryEmbedding = await neuralForge.getEmbedding(query);
43	        if (!queryEmbedding) {
44	            onError('Failed to generate query embedding. Is Ollama running?');
45	            return;
46	        }
47	
48	        const topChunks = this.retrieveTopK(embeddedChunks, queryEmbedding, TOP_K);
49	
50	        // Emit citations for all retrieved chunks
51	        for (const chunk of topChunks) {
52	            onCitation({
53	                chunk_id: chunk.id,
54	                source_title: chunk.source_title,
55	                excerpt: chunk.content.slice(0, 200) + (chunk.content.length > 200 ? '…' : '')
56	            });
57	        }
58	
59	        const systemPrompt = this.buildSystemPrompt(topChunks);
60	        const usedChunkIds = topChunks.map(c => c.id);
61	
62	        try {
63	            const upstream = await fetch(`${OLLAMA_BASE}/api/chat`, {
64	                method: 'POST',
65	                headers: { 'Content-Type': 'application/json' },
66	                body: JSON.stringify({
67	                    model: modelId,
68	                    messages: [
69	                        { role: 'system', content: systemPrompt },
70	                        { role: 'user', content: query }
71	                    ],
72	                    stream: true
73	                }),
74	                signal
75	            });
76	
77	            if (!upstream.ok) throw new Error(`Ollama HTTP ${upstream.status}`);
78	            if (!upstream.body) throw new Error('No response body');
79	
80	            let fullContent = '';
81	            const reader = upstream.body.getReader();
82	            const decoder = new TextDecoder();
83	
84	            while (true) {
85	                const { done, value } = await reader.read();
86	                if (done) break;
87	                const text = decoder.decode(value, { stream: true });
88	                for (const line of text.split('\n').filter(Boolean)) {
89	                    try {
90	                        const parsed = JSON.parse(line);
91	                        const token = parsed?.message?.content || '';
92	                        if (token) {
93	                            fullContent += token;
94	                            onToken(token);
95	                        }
96	                        if (parsed?.done) break;
97	                    } catch (_) {}
98	                }
99	            }
100	
101	            this.notebookService.saveMessage(notebookId, 'assistant', fullContent, usedChunkIds);
102	            onDone(fullContent);
103	        } catch (e: any) {
104	            if (e.name !== 'AbortError') {
105	                onError(e.message || 'RAG_STREAM_FAILED');
106	            }
107	        }
108	    }
109	
110	    private retrieveTopK(chunks: EmbeddedChunk[], queryVec: number[], k: number): EmbeddedChunk[] {
111	        return chunks
112	            .filter(c => c.embedding != null)
113	            .map(c => ({
114	                chunk: c,
115	                score: this.cosineSimilarity(queryVec, JSON.parse(c.embedding!))
116	            }))
117	            .sort((a, b) => b.score - a.score)
118	            .slice(0, k)
119	            .map(r => r.chunk);
120	    }
121	
122	    private buildSystemPrompt(chunks: EmbeddedChunk[]): string {
123	        const contextBlocks = chunks.map((c, i) =>
124	            `[SOURCE ${i + 1}: ${c.source_title}]\n${c.content}`
125	        ).join('\n\n---\n\n');
126	
127	        return [
128	            'You are an expert research assistant with access to the following source material.',
129	            'Answer the user\'s question based ONLY on the provided sources.',
130	            'Be thorough, accurate, and cite sources naturally (e.g., "According to [SOURCE 1]...").',
131	            'If the sources don\'t contain enough information, say so clearly.',
132	            '',
133	            '## Source Material',
134	            '',
135	            contextBlocks
136	        ].join('\n');
137	    }
138	
139	    private cosineSimilarity(vecA: number[], vecB: number[]): number {
140	        let dot = 0, normA = 0, normB = 0;
141	        for (let i = 0; i < vecA.length; i++) {
142	            dot += vecA[i] * vecB[i];
143	            normA += vecA[i] * vecA[i];
144	            normB += vecB[i] * vecB[i];
145	        }
146	        if (normA === 0 || normB === 0) return 0;
147	        return dot / (Math.sqrt(normA) * Math.sqrt(normB));
148	    }
149	}
