188	export function streamGenerate(notebookId: number, docType: DocType, model: string, callbacks: DocGenCallbacks): EventSource {
189	    const url = `${API_ORIGINS[0]}/api/notebook/notebooks/${notebookId}/generate`;
190	    // POST with SSE isn't standard — we use fetch + ReadableStream here
191	    const es = new (class extends EventTarget {
192	        close() {}
193	    } as any)();
194	
195	    (async () => {
196	        try {
197	            const r = await apiFetch(`/api/notebook/notebooks/${notebookId}/generate`, {
198	                method: 'POST',
199	                headers: { 'Content-Type': 'application/json' },
200	                body: JSON.stringify({ doc_type: docType, model_id: model })
201	            });
202	            if (!r.ok || !r.body) throw new Error(`HTTP ${r.status}`);
203	
204	            const reader = r.body.getReader();
205	            const decoder = new TextDecoder();
206	            let buffer = '';
207	            let lastEvent = '';
208	
209	            while (true) {
210	                const { done, value } = await reader.read();
211	                if (done) break;
212	                buffer += decoder.decode(value, { stream: true });
213	                const lines = buffer.split('\n');
214	                buffer = lines.pop() || '';
215	                for (const line of lines) {
216	                    if (line.startsWith('event:')) {
217	                        lastEvent = line.slice(6).trim();
218	                    } else if (line.startsWith('data:')) {
219	                        try {
220	                            const data = JSON.parse(line.slice(5).trim());
221	                            if (lastEvent === 'token' && data.token !== undefined) callbacks.onToken(data.token);
222	                            if (lastEvent === 'done' && data.docId !== undefined) callbacks.onDone(data.docId);
223	                            if (lastEvent === 'error' && data.message !== undefined) callbacks.onError(data.message);
224	                        } catch (_) {}
225	                    }
226	                }
227	            }
228	        } catch (e: any) {
229	            callbacks.onError(e.message || 'GENERATE_FAILED');
230	        }
231	    })();
232	
233	    return es;
234	}
